mapper.select:
SELECT p.product_id, p.member_id, p.category_id, p.title, p.description, p.condition, p.model_name, p.release_year, p.market_price, p.thumbnail_url, p.status, p.created_at, p.updated_at, p.deleted_at FROM product p
p.deleted_at IS NULL AND p.status <> 'HIDDEN'::product_status
AND p.status = #{cond.status}::product_status
AND p.category_id = #{cond.categoryId}
AND p.market_price >= #{cond.minPrice}
AND p.market_price <= #{cond.maxPrice}
AND (p.created_at, p.product_id) < (#{cond.cursorCreatedAt}, #{cond.cursorProductId})
ORDER BY p.created_at DESC, p.product_id DESC LIMIT #{cond.limit}
